Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/gallery.ListView */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    <h1>{{.Title}}</h1>
    {{range .Albums}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            <h3>{{.Title}}</h3>
            <div>{{.Description}}</div>
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            {{if .CoverURL}}<img src="{{.CoverURL}}"{{with .CoverSrcset}} srcset="{{.}}" sizes="100vw"{{end}} alt="">{{end}}
            {{/* CoverOriginalURL: {{.CoverOriginalURL}} — the uploaded file, for a download link */}}
            <p>ImageCount: {{.ImageCount}}</p>
            {{range .Images}}
                <article>
                </article>
            {{end}}
        </article>
    {{end}}
</main>

{{/* @dot github.com/donseba/go-webthings/modules/gallery.Album */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    {{/* ID: {{.ID}} — stable, usable as an anchor */}}
    <h1>{{.Title}}</h1>
    <div>{{.Description}}</div>
    {{with .URL}}<a href="{{.}}">URL</a>{{end}}
    {{if .CoverURL}}<img src="{{.CoverURL}}"{{with .CoverSrcset}} srcset="{{.}}" sizes="100vw"{{end}} alt="">{{end}}
    {{/* CoverOriginalURL: {{.CoverOriginalURL}} — the uploaded file, for a download link */}}
    <p>ImageCount: {{.ImageCount}}</p>
    {{range .Images}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
            {{with .Srcset}}<p>{{.}}</p>{{end}}
            <p>Width: {{.Width}}</p>
            <p>Height: {{.Height}}</p>
            {{with .LargeURL}}<a href="{{.}}">LargeURL</a>{{end}}
            {{/* OriginalURL: {{.OriginalURL}} — the uploaded file, for a download link */}}
            <h3>{{.Title}}</h3>
            {{with .Alt}}<p>{{.}}</p>{{end}}
        </article>
    {{end}}
</main>

Types.Decl:
type APIAlbum struct {
	ID    string `json:"id"`
	Slug  string `json:"slug"`
	Title string `json:"title"`
	// DescriptionHTML is the album's description as HTML (api.HTML); only
	// the album's own endpoint has it.
	DescriptionHTML string `json:"description_html,omitempty"`
	// Cover is the cover image, or the first image when the editors chose
	// none; null for an album without images.
	Cover      *api.Image `json:"cover"`
	ImageCount int        `json:"image_count"`
	// URL is the album's page, null while the gallery is on no page; APIURL
	// the album in the API.
	URL       *string   `json:"url"`
	APIURL    string    `json:"api_url"`
	UpdatedAt time.Time `json:"updated_at"`
}

type APIImage struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	api.Image
}

type Album struct {
	ID          string
	Title       string
	Description template.HTML
	// URL is the album's page, empty when the gallery is on no page.
	URL string
	// CoverURL is the cover as pages show it, at most media.ImageWidth wide;
	// CoverSrcset lists smaller copies for a srcset attribute, CoverWidth
	// and CoverHeight are the size of CoverURL and CoverOriginalURL is the
	// uploaded file. All are empty for an album without images.
	CoverURL         string
	CoverSrcset      string
	CoverOriginalURL string
	CoverWidth       int
	CoverHeight      int
	ImageCount       int
	Images           []Image
}

type AlbumFields struct {
	Cover  string      `db:"cover_id,null"`
	Images content.IDs `db:"image_ids"`
}

type AlbumText struct {
	Slug        string `db:"slug"`
	Title       string `db:"title"`
	Description string `db:"description"`
}

type Image struct {
	ID string
	// URL is the image as pages show it, at most media.ImageWidth wide, and
	// Srcset smaller copies for a srcset attribute; Width and Height are the
	// size of URL.
	URL    string
	Srcset string
	Width  int
	Height int
	// LargeURL is a copy at most media.LargeImageWidth wide, for the image
	// on its own, such as in a lightbox.
	LargeURL string
	// OriginalURL is the uploaded file, for downloads.
	OriginalURL string
	Title       string
	Alt         string
}

type ImageRow struct {
	Name string
	// URL shows the image; it is empty when the file is no longer in the
	// media library.
	URL string
	// Moves are the image's up and down arrows; nil without the right to
	// edit albums.
	Moves []admin.Move
}

type ImagesView struct {
	Title   string
	BackURL string
	EditURL string
	Images  []ImageRow
}

type ListView struct {
	Title  string
	Albums []Album
}

type OrderAlbum struct {
	Title string
	// URL opens the images of the album.
	URL    string
	Images int
}

type OrderView struct {
	BackURL string
	// BackLabel names the albums overview BackURL leads to, as a
	// translation key.
	BackLabel string
	Albums    []OrderAlbum
}

type Service struct {
	// contains unexported fields
}
